//! R036/02: Atomic multi-file create operation. Real guest filesystem/workstation operation.
use super::Error;
use crate::batch7_ramfs::{RamFs,CONTENT_MAX,PATH_MAX};
pub fn create<const F:usize,const B:usize>(fs:&mut RamFs<F>,expected:u64,items:&[(&[u8],&[u8])])->Result<usize,Error>{if fs.version()!=expected{return Err(Error::Stale);}if items.is_empty(){return Err(Error::Invalid);}let mut snapshot=[0;B];let n=fs.export_snapshot(&mut snapshot).map_err(|_|Error::Full)?;let mut staged=RamFs::<F>::new();staged.import_snapshot(&snapshot[..n]).map_err(|_|Error::Invalid)?;for (i,(path,bytes)) in items.iter().enumerate(){if fs.metadata(path).is_ok()||items[..i].iter().any(|(p,_)|p==path){return Err(Error::Conflict);}staged.replace(path,bytes).map_err(|_|Error::Full)?;}let mut image=[0;B];let n=staged.export_snapshot(&mut image).map_err(|_|Error::Full)?;fs.import_snapshot(&image[..n]).map_err(|_|Error::Invalid)?;Ok(items.len())}
#[cfg(test)]mod tests{use super::*;#[test]fn real_functional_regression(){let mut fs=RamFs::<3>::new();assert_eq!(create::<3,8192>(&mut fs,0,&[(b"/p/a",b"a"),(b"/p/b",b"b")]),Ok(2));assert_eq!(fs.count(),2);assert!(create::<3,8192>(&mut fs,2,&[(b"/p/a",b"bad")]).is_err());}}
